```javascript
// Create sprite sheet loader with animation frames
class SpriteSheet {
    constructor(imageSrc, frameWidth, frameHeight, totalFrames) {
        this.image = new Image();
        this.image.src = imageSrc;
        this.frameWidth = frameWidth;
        this.frameHeight = frameHeight;
        this.totalFrames = totalFrames;
        this.currentFrame = 0;
    }

    draw(ctx, x, y, flipX = false) {
        let frameX = (this.currentFrame % Math.floor(this.image.width / this.frameWidth)) * this.frameWidth;
        let frameY = Math.floor(this.currentFrame / Math.floor(this.image.width / this.frameWidth)) * this.frameHeight;

        ctx.save();
        if (flipX) ctx.scale(-1, 1);
        ctx.drawImage(this.image, frameX, frameY, this.frameWidth, this.frameHeight,
                     flipX ? x - this.frameWidth : x, y, this.frameWidth, this.frameHeight);
        ctx.restore();
    }
}
```

**2. Build Tilemap System with Collision**
```javascript
class Tilemap {
    constructor(data, tileSize) {
        this.data = data; // 2D array [[0,1,0],[0,0,2]]
        this.tileSize = tileSize;
        this.layers = {
            'collision': this.createCollisionLayer(),
            'environment': this.createEnvironmentLayer()
        };
    }

    createCollisionLayer() {
        let layer = [];
        for (let y = 0; y < this.data.length; y++) {
            layer[y] = [];
            for (let x = 0; x < this.data[y].length; x++) {
                let tileType = this.data[y][x];
                layer[y][x] = {
                    walkable: tileType !== 1 && tileType !== 2, // 1=wall, 2=water
                    solid: tileType === 1, // walls are solid
                    type: tileType
                };
            }
        }
        return layer;
    }

    checkCollision(x, y, width, height) {
        let left = Math.floor(x / this.tileSize);
        let right = Math.floor((x + width) / this.tileSize);
        let top = Math.floor(y / this.tileSize);
        let bottom = Math.floor((y + height) / this.tileSize);

        for (let y = top; y <= bottom; y++) {
            for (let x = left; x <= right; x++) {
                if (y >= 0 && y < this.layers.collision.length && 
                    x >= 0 && x < this.layers.collision[y].length) {
                    if (!this.layers.collision[y][x].walkable) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}
