**3. Implement Combat System**
```javascript
class CombatSystem {
    constructor(engine) {
        this.engine = engine;
        this.combatLog = [];
    }

    processCombat(attacker, defender) {
        // Calculate damage
        let damage = attacker.stats.attack - defender.stats.defense;
        damage = Math.max(1, damage); // Minimum 1 damage

        // Apply damage
        defender.stats.currentHP -= damage;

        // Check for critical hit
        if (Math.random() < 0.1) { // 10% crit chance
            damage *= 2;
            defender.stats.currentHP -= damage;
            this.combatLog.push(`${attacker.name} CRITICAL HIT! ${defender.name} took ${damage} damage!`);
        } else {
            this.combatLog.push(`${attacker.name} hit ${defender.name} for ${damage} damage!`);
        }

        // Check for defeat
        if (defender.stats.currentHP <= 0) {
            defender.die();
            this.combatLog.push(`${defender.name} has been defeated!`);
            this.awardExperience(attacker, defender);
        }
    }

    awardExperience(attacker, defeated) {
        let player = this.engine.entities.find(e => e instanceof Player);
        if (player) {
            player.gainExperience(defeated.experienceValue);
            player.gold += defeated.goldValue;
        }
    }
}
