class StateMachine {
    constructor(entity) {
        this.entity = entity;
        this.states = {};
        this.currentState = null;
        this.stateHistory = [];
    }

    addState(name, behavior) {
        this.states[name] = behavior;
        this.states[name].name = name;
        this.states[name].entity = this.entity;
    }

    transitionTo(stateName, ...args) {
        if (!this.states[stateName]) {
            console.warn(`State ${stateName} not found`);
            return;
        }

        // Exit current state
        if (this.currentState && this.currentState.exit) {
            this.currentState.exit(...args);
        }

        // Enter new state
        this.previousState = this.currentState;
        this.currentState = this.states[stateName];

        if (this.currentState.enter) {
            this.currentState.enter(...args);
        }

        this.stateHistory.push(stateName);
    }

    update(deltaTime, ...args) {
        if (this.currentState && this.currentState.update) {
            this.currentState.update(deltaTime, ...args);
        }
    }
}

