        enter() { this.patrolPointsIndex = 0; },
        update(deltaTime) {
            // Move to patrol point
            let target = this.patrolPoints[this.patrolPointsIndex];
            let distance = Math.sqrt(Math.pow(target.x - this.transform.x, 2) + 
                                    Math.pow(target.y - this.transform.y, 2));

            if (distance < 10) {
                this.patrolPointsIndex = (this.patrolPointsIndex + 1) % this.patrolPoints.length;
            } else {
                let angle = Math.atan2(target.y - this.transform.y, target.x - this.transform.x);
                this.physics.velocity.x = Math.cos(angle) * this.stats.speed;
                this.physics.velocity.y = Math.sin(angle) * this.stats.speed;
            }

            // Check for player
            let player = this.engine.entities.find(e => e instanceof Player);
            if (player) {
                let playerDistance = Math.sqrt(Math.pow(player.transform.x - this.transform.x, 2) + 
                                             Math.pow(player.transform.y - this.transform.y, 2));
                if (playerDistance < this.attackRange) {
                    this.stateMachine.transitionTo('chase', player);
                }
            }
        }
    },

    chase: {
        enter(target) {
            this.chaseTarget = target;
        },
        update(deltaTime) {
            if (!this.chaseTarget || this.chaseTarget.stats.currentHP <= 0) {
                this.stateMachine.transitionTo('patrol');
                return;
            }

            let distance = Math.sqrt(Math.pow(this.chaseTarget.transform.x - this.transform.x, 2) + 
                                    Math.pow(this.chaseTarget.transform.y - this.transform.y, 2));

            if (distance > this.attackRange * 1.5) {
                // Move toward player
                let angle = Math.atan2(this.chaseTarget.transform.y - this.transform.y, 
                                     this.chaseTarget.transform.x - this.transform.x);
                this.physics.velocity.x = Math.cos(angle) * this.stats.speed;
                this.physics.velocity.y = Math.sin(angle) * this.stats.speed;
                this.sprite.flipX = this.chaseTarget.transform.x < this.transform.x;
            } else if (distance <= this.attackRange) {
                this.performAttack();
            } else {
                // Back away
                let angle = Math.atan2(this.transform.y - this.chaseTarget.transform.y, 
                                     this.transform.x - this.chaseTarget.transform.x);
                this.physics.velocity.x = Math.cos(angle) * this.stats.speed * 0.5;
                this.physics.velocity.y = Math.sin(angle) * this.stats.speed * 0.5;
            }
        }
    },

    attack: {
        enter() {
            this.isAttacking = true;
            this.attackCooldown = this.maxAttackCooldown;
        },
        update(deltaTime) {
            if (this.isAttacking) {
                // Play attack animation
                this.sprite.currentFrame = 2; // attack frame

                // Check if attack animation completed
                if (this.attackTimer > this.attackDuration) {
                    this.isAttacking = false;
                    this.sprite.currentFrame = 0; // idle frame
                    this.stateMachine.transitionTo('hurt');
                }
            }

            if (this.attackCooldown > 0) {
                this.attackCooldown -= deltaTime;
            }
        },
        exit() {
            this.isAttacking = false;
        }
    },

    hurt: {
        enter() {
            // Play hurt animation
            this.sprite.currentFrame = 3; // hurt frame
            this.hurtDuration = 0.5; // 0.5 seconds
            this.hurtTimer = 0;
        },
        update(deltaTime) {
            this.hurtTimer += deltaTime;

            if (this.hurtTimer >= this.hurtDuration) {
                // Check if should return to patrol or chase
                let player = this.engine.entities.find(e => e instanceof Player);
                if (player) {
                    let distance = Math.sqrt(Math.pow(player.transform.x - this.transform.x, 2) + 
                                            Math.pow(player.transform.y - this.transform.y, 2));
                    if (distance < this.attackRange) {
                        this.stateMachine.transitionTo('chase', player);
                    } else {
                        this.stateMachine.transitionTo('patrol');
                    }
                } else {
                    this.stateMachine.transitionTo('patrol');
                }
            }
        }
    }
};
