class SaveSystem {
    constructor(engine) {
        this.engine = engine;
    }

    saveGame(filename = 'savegame.json') {
        let saveData = {
            timestamp: Date.now(),
            player: this.serializePlayer(),
            entities: this.serializeEntities(),
            worldState: this.serializeWorldState()
        };

        localStorage.setItem(`save_${filename}`, JSON.stringify(saveData));
        return saveData;
    }

    serializePlayer() {
        let player = this.engine.entities.find(e => e instanceof Player);
        if (!player) return null;

        return {
            id: player.id,
            name: player.name,
            level: player.level,
            experience: player.experience,
            gold: player.gold,
            stats: {
                currentHP: player.stats.currentHP,
                maxHP: player.stats.maxHP,
                currentMP: player.stats.currentMP,
                maxMP: player.stats.maxMP,
                attack: player.stats.attack,
                defense: player.stats.defense,
                speed: player.stats.speed
            },
            position: {
                x: player.transform.x,
                y: player.transform.y
            },
            equipment: player.equipment,
            skills: player.skills,
            quests: player.quests,
            cosmetics: player.cosmetics
        };
    }

    loadGame(filename = 'savegame.json') {
        let saveData = localStorage.getItem(`save_${filename}`);
        if (!saveData) {
            console.log('No save file found');
            return null;
        }

        saveData = JSON.parse(saveData);

        // Restore player
        this.restorePlayer(saveData.player);

        // Restore entities
        this.restoreEntities(saveData.entities);

        // Restore world state
        this.restoreWorldState(saveData.worldState);

        return saveData;
    }

    restorePlayer(playerData) {
        let player = this.engine.entities.find(e => e instanceof Player);
        if (!player) return;

        // Restore all player properties
        player.level = playerData.level;
        player.experience = playerData.experience;
        player.gold = playerData.gold;
        player.stats.currentHP = playerData.stats.currentHP;
        player.stats.maxHP = playerData.stats.maxHP;
        player.stats.currentMP = playerData.stats.currentMP;
        player.stats.maxMP = playerData.stats.maxMP;
        player.stats.attack = playerData.stats.attack;
        player.stats.defense = playerData.stats.defense;
        player.stats.speed = playerData.stats.speed;

        player.transform.x = playerData.position.x;
        player.transform.y = playerData.position.y;
        player.equipment = playerData.equipment;
        player.skills = playerData.skills;
        player.quests = playerData.quests;
        player.cosmetics = playerData.cosmetics;

        // Update UI
        this.updatePlayerUI();
    }

    updatePlayerUI() {
        let player = this.engine.entities.find(e => e instanceof Player);
        if (!player) return;

        document.getElementById('infoLevel').textContent = player.level;
        document.getElementById('infoHP').textContent = player.stats.currentHP;
        document.getElementById('infoMaxHP').textContent = player.stats.maxHP;
        document.getElementById('infoMP').textContent = player.stats.currentMP;
        document.getElementById('infoMaxMP').textContent = player.stats.maxMP;
        document.getElementById('infoEXP').textContent = player.experience;
        document.getElementById('infoMaxEXP').textContent = player.getMaxExperience();
        document.getElementById('infoGold').textContent = player.gold;
    }
}
