**6. Implement Delta Time Optimization**
```javascript
class PerformanceOptimizer {
    constructor(engine) {
        this.engine = engine;
        this.frameCount = 0;
        this.lastFPSCheck = Date.now();
        this.currentFPS = 60;
    }

    optimizeUpdate(deltaTime) {
        // Cap delta time to prevent spiral of death
        const maxDeltaTime = 0.1; // 100ms max
        deltaTime = Math.min(deltaTime, maxDeltaTime);

        // Apply time scale
        deltaTime *= this.engine.timeScale;

        // Smooth delta time for physics
        this.engine.deltaTime = this.lerp(this.engine.deltaTime, deltaTime, 0.1);

        return this.engine.deltaTime;
    }

    lerp(start, end, factor) {
        return start * (1 - factor) + end * factor;
    }

    checkFPS() {
        this.frameCount++;
        const currentTime = Date.now();

        if (currentTime - this.lastFPSCheck >= 1000) {
            this.currentFPS = this.frameCount;
            this.frameCount = 0;
            this.lastFPSCheck = currentTime;

            // Adjust physics timestep based on FPS
            if (this.currentFPS < 50) {
                this.engine.fixedDeltaTime = 0.02; // Slower physics
            } else {
                this.engine.fixedDeltaTime = 0.016; // 60 FPS
            }
        }
    }
}
