class GameSelfAssessment {
    constructor(engine) {
        this.engine = engine;
        this.assessment = {
            featuresImplemented: 0,
            totalFeatures: 0,
            issuesFound: [],
            recommendations: []
        };
    }

    assessGame() {
        console.log('=== SELF-ASSESSMENT REPORT ===');

        // Count implemented features
        this.countFeatures();

        // Check for critical issues
        this.checkCriticalIssues();

        // Provide recommendations
        this.provideRecommendations();

        // Calculate completion percentage
        const completionPercentage = (this.assessment.featuresImplemented / this.assessment.totalFeatures) * 100;

        console.log(`\n📊 Completion: ${this.assessment.featuresImplemented}/${this.assessment.totalFeatures} features (${completionPercentage.toFixed(1)}%)`);

        if (this.assessment.issuesFound.length > 0) {
            console.log('\n❌ Issues Found:');
            this.assessment.issuesFound.forEach((issue, index) => {
                console.log(`  ${index + 1}. ${issue}`);
            });
        }

        if (this.assessment.recommendations.length > 0) {
            console.log('\n💡 Recommendations:');
            this.assessment.recommendations.forEach((rec, index) => {
                console.log(`  ${index + 1}. ${rec}`);
            });
        }

        console.log('\n=== ASSESSMENT COMPLETE ===');

        return {
            completionPercentage,
            issues: this.assessment.issuesFound,
            recommendations: this.assessment.recommendations
        };
    }

    countFeatures() {
        // Core RPG features from specification
        const coreFeatures = [
            'Entity Component System',
            'State Machine',
            'Player Character',
            'Enemy AI',
            'Combat System',
            'Equipment System',
            'Inventory Management',
            'Quest System',
            'Experience/Gaining',
            'Leveling System',
            'Skill Trees',
            'Save/Load System',
            'Map/Exploration',
            'NPC Interactions',
            'UI/HUD',
            'Audio System',
            'Graphics/Rendering',
            'Input/Controls',
            'Physics/Collision',
            'Animation System',
            'Localization Support'
        ];

        this.assessment.totalFeatures = coreFeatures.length;

        // Check which features are implemented
        const player = this.engine.entities.find(e => e instanceof Player);
        if (player) this.assessment.featuresImplemented++;

        const enemy = this.engine.entities.find(e => e instanceof Enemy);
        if (enemy) this.assessment.featuresImplemented++;

        if (this.engine.hasComponent('Transform')) this.assessment.featuresImplemented++;
        if (this.engine.hasComponent('Sprite')) this.assessment.featuresImplemented++;
        if (this.engine.hasComponent('Stats')) this.assessment.featuresImplemented++;
        if (this.engine.hasComponent('Physics')) this.assessment.featuresImplemented++;
        if (this.engine.hasComponent('Inventory')) this.assessment.featuresImplemented++;
        if (this.engine.hasComponent('AI')) this.assessment.featuresImplemented++;

        // Check for combat system
        if (this.engine.systems.some(s => s.constructor.name === 'CombatSystem')) {
            this.assessment.featuresImplemented++;
        }

        // Check for save system
        if (this.engine.saveSystem) {
            this.assessment.featuresImplemented++;
        }
    }

    checkCriticalIssues() {
        // Check for missing critical systems
        const player = this.engine.entities.find(e => e instanceof Player);
        if (!player) {
            this.assessment.issuesFound.push('No player character entity');
        }

        if (!player || !player.hasComponent('Transform')) {
            this.assessment.issuesFound.push('Player missing transform component');
        }

        if (!player || !player.hasComponent('Stats')) {
            this.assessment.issuesFound.push('Player missing stats component');
        }

        // Check for combat implementation
        const enemy = this.engine.entities.find(e => e instanceof Enemy);
        if (enemy && (!enemy.performAttack || typeof enemy.performAttack !== 'function')) {
            this.assessment.issuesFound.push('Enemy combat system incomplete');
        }

        // Check state machine
        if (enemy && (!enemy.stateMachine || !enemy.stateMachine.currentState)) {
            this.assessment.issuesFound.push('Enemy state machine not implemented');
        }
    }

    provideRecommendations() {
        if (this.assessment.featuresImplemented < this.assessment.totalFeatures * 0.8) {
            this.assessment.recommendations.push('Focus on implementing missing core RPG features');
        }

        if (this.assessment.issuesFound.includes('Player missing transform component')) {
            this.assessment.recommendations.push('Add Transform component to player entity');
        }

        if (this.assessment.issuesFound.includes('Enemy combat system incomplete')) {
            this.assessment.recommendations.push('Implement enemy attack and combat logic');
        }

        if (this.assessment.issuesFound.includes('Enemy state machine not implemented')) {
            this.assessment.recommendations.push('Add state machine to enemy entities');
        }

        this.assessment.recommendations.push('Test game thoroughly before deployment');
        this.assessment.recommendations.push('Optimize performance for target 60 FPS');
        this.assessment.recommendations.push('Add more content (maps, items, quests)');
    }
}
